decoradores:
@ValidateBy({
    name: 'linesOrCharges',
    validator: {
      validate: (value: unknown, args): boolean =>
        (Array.isArray(value) && value.length > 0) ||
        (Array.isArray(
          (args?.object as { chargeCaptureIds?: unknown }).chargeCaptureIds,
        ) &&
          ((args?.object as { chargeCaptureIds: unknown[] }).chargeCaptureIds
            .length ?? 0) > 0),
      defaultMessage: () =>
        'lines must contain at least 1 elements (o enviar chargeCaptureIds)',
    },
  })
